import '../../../globals'
import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Row, Col, Button, Form, Input, Radio, Select, Alert, Spin, message } from 'antd'
import { includes, size, omit } from 'lodash'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import QueryString from 'query-string'
import EditTemplateStyled from './editTemplate.style'
import NotificationActions from '../../redux/notifications/actions'
// import Trumbowyg from 'react-trumbowyg'
import { HTMLStyled as HtmlEditorStyled } from './htmlEditor.styled'
import HTMLPreviewer from './configurableTemplates'
import partnerGroupActions from '../../redux/partner/actions'
import insuranceActions from '../../../redux/policy/actions'
const {
  getMasterData, updateTemplate, resetNotificationsRedux,
  closeViewBodyHtml, addTemplate, resetNotificationCore
} = NotificationActions
const { getPartners } = insuranceActions
const {
  getPartnerProductTemplateDataRequest
} = partnerGroupActions
const FormItem = Form.Item
const { TextArea } = Input
const Option = Select.Option
const RadioGroup = Radio.Group

class AddTemplate extends Component {
  state = {
    masterData: {},
    queryString: QueryString.parse(this.props.location.search),
    submitting: false,
    plainTextSelected: true,
    plainEditor: '',
    paramsObject: [{ id: 0, value: '' }],
    htmlContent: '',
    showThirdPartyFields: ['whatsapp', 'mobile_app_push', 'zalo', 'whatsapp_twilio'],
    subjectField: ['email', 'mobile_app_push'],
    selectedProduct: ''
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      masterData,
      getMasterDataStatus,
      addTemplateStatus
    } = nextProps.Notifications
    if (getMasterDataStatus !== '') {
      this.setState({ masterData, getMasterDataStatus })
    }
    if (addTemplateStatus !== '') {
      this.setState({ addTemplateStatus, submitting: false })
    }
    if (addTemplateStatus !== '' && addTemplateStatus === 'success') {
      // $('#body').trumbowyg('empty')
      this.props.form.setFieldsValue({
        code: '',
        description: '',
        notification_type: '',
        subject: '',
        body_text: '',
        body: ''
      })
      this.props.resetNotificationCore()
    }
  }

  componentDidMount () {
    this.props.getMasterData()
  }

  componentWillUnmount () {
    this.props.resetNotificationsRedux()
    this.props.closeViewBodyHtml()
  }

  handleOnBack = () => {
    const { history } = this.props
    history.push('/notifications')
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  handleOnSubmit = async e => {
    e.preventDefault()
    this.setState({ submit: true })
    const html = this.state.htmlContent
    // if (html === '') {
    //   this.setState({ isHtmlEmpty: '' })
    //   this.props.form.setFields({
    //     'body': {
    //       value: '',
    //       errors: [new Error('Main body can not be empty')]
    //     }
    //   })
    //   return
    // }
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    this.setState({ submitting: true })
    const { form } = this.props
    const { paramsObject } = this.state
    let data = form.getFieldsValue()

    if (data.body === undefined) {
      data = { ...data, body: html }
    }
    if (data.third_party_template_status === undefined) {
      data = { ...data, third_party_template_status: 0 }
    }
    if (data.third_party_template_id === '' || data.third_party_template_id === undefined) {
      data = { ...data, third_party_template_id: null }
    }
    if (this.state.notificationType === 'sms') {
      data = { ...data, subject: '' }
    }
    if (this.state.plainTextSelected) {
      data = { ...data, body: this.state.plainEditor }
    }

    // const filteredParamsObject = paramsObject.filter(n => n)
    // const params = assign({}, filteredParamsObject)
    const params = {}
    if (size(paramsObject) > 0) {
      paramsObject.forEach((item, index) => {
        if (item.value) {
          params[index] = item.value
        }
      })
    }
    data = { ...data, third_party_template_parameter: params }
    data = omit(data, ['params'])
    this.props.addTemplate(data)
  }

  handleEditorChange = (e) => {
    this.setState({
      htmlContent: e.target.innerHTML,
      isHtmlEmpty: e.target.innerHTML
    })
  }

  handleOnCloseAlert = () => {
    this.props.resetNotificationsRedux()
    this.setState({ addTemplateStatus: '' })
  }

  handleOnNotificationType = notificationType => {
    this.setState({ notificationType })
    if (notificationType !== 'email') {
      this.setState({ plainTextSelected: true })
    }
  }

  handleOnEditorChange = (e) => {
    this.setState({
      plainTextSelected: e.target.value
    }, () => {
      if (!e.target.value) {
        this.props.getPartners()
      }
    })
  }

  onChangeEditorPlain = e => {
    this.setState({ plainEditor: e.target.value })
  }

  getLangugeCodes = () => {
    const { masterData } = this.state
    let languageOptions = ''
    if (masterData.language_codes) {
      languageOptions = masterData.language_codes.map(d => <Option value={d.code} key={d.id}>{d.description}</Option>
      )
    }
    return languageOptions
  }

  handleOptions = index => {
    const { paramsObject } = this.state
    const newOption = paramsObject.filter((item) => { return item.id !== index })
    if (newOption.length < 1) {
      message.error('Atleast one option required')
      return
    }
    this.setState({ paramsObject: newOption })
  }

  addOptions = () => {
    const { paramsObject } = this.state
    const index = paramsObject[paramsObject.length - 1].id + 1
    this.setState(prevState => ({
      paramsObject: [...prevState.paramsObject,
        { id: index, value: '' }
      ]
    }))
  }

  onChangeInput = (e, id) => {
    const { paramsObject } = this.state
    const object = paramsObject.find(item => item.id === id)
    object.value = e.target.value
    this.setState({ paramsObject: paramsObject })
  }

  gettingDynamicHTML =(data) => {
    this.setState({
      htmlContent: data
    })
  }

  onChangePartner=(e) => {
    this.props.getPartnerProductTemplateDataRequest({ query: { partner: e } })
  }

  onChangeProduct=(val) => {
    this.setState({
      selectedProduct: val
    })
  }

  render () {
    const { masterData, submitting, paramsObject, notificationType, showThirdPartyFields, subjectField, selectedProduct } = this.state
    const { form } = this.props
    const { getFieldDecorator } = form
    const radioStyle = {
      display: 'block',
      height: '30px',
      lineHeight: '30px'
    }

    return (
      <LayoutContentWrapper>
        {
          (this.state.addTemplateStatus !== '' && this.state.addTemplateStatus === 'success') && (
            <Row style={{ width: '100%', marginBottom: '10px' }}>
              <Col>
                <Alert
                  message={this.state.addTemplateStatus}
                  type='success'
                  closable
                  onClose={this.handleOnCloseAlert}
                />
              </Col>
            </Row>
          )
        }
        {
          (this.state.addTemplateStatus !== '' && this.state.addTemplateStatus !== undefined && this.state.addTemplateStatus !== 'success') && (
            <Row style={{ width: '100%', marginBottom: '10px' }}>
              <Col>
                <Alert
                  message={this.state.addTemplateStatus}
                  type='error'
                  closable
                  onClose={this.handleOnCloseAlert}
                />
              </Col>
            </Row>
          )
        }
        <LayoutContent>
          <EditTemplateStyled>
            <Row>
              <Col span={24} xs={24}>
                <Button onClick={this.handleOnBack}>Back</Button>
              </Col>
              <Spin spinning={this.state.submitting}>
                <Form
                  onSubmit={this.handleOnSubmit}
                  style={{ marginTop: '20px' }}
                  id='addTemplate'
                >
                  <Row gutter={24}>
                    <Col span={12} xs={24}>
                      <Row type='flex' gutter={10}>
                        <Col xl={12} xs={24}>
                          <FormItem
                            label='Unique template code'
                            extra='eg: tmpl-claim-creation-email-01'
                          >
                            {getFieldDecorator('code', {
                              rules: [
                                { required: true, message: 'Unique template code can not be empty' }
                              ]
                            })(
                              <Input size='default' className='input-box' />
                            )}
                          </FormItem>
                        </Col>
                        <Col xl={12} xs={24}>
                          <FormItem
                            label='Language'
                          >
                            {getFieldDecorator('language_code', {
                              rules: [
                                { required: true, message: 'language_code can not be empty' }
                              ]
                            })(
                              <Select
                                showSearch
                                placeholder='Select ...'
                                style={{ width: '100%' }}
                                filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                              >
                                {this.getLangugeCodes()}
                              </Select>
                            )}
                          </FormItem>
                        </Col>
                        <Col xl={12} xs={24}>
                          <FormItem
                            label='Description'
                          >
                            {getFieldDecorator('description', {
                              rules: [
                                { required: true, message: 'Description can not be empty' }
                              ]
                            })(
                              <Input size='default' className='input-box' />
                            )}
                          </FormItem>
                        </Col>
                        <Col xl={12} xs={24}>
                          <FormItem
                            label='Type'
                          >
                            {getFieldDecorator('notification_type', {
                              rules: [
                                { required: true, message: 'Notification type can not be empty' }
                              ]
                            })(
                              <Select
                                showSearch
                                placeholder='Select ...'
                                style={{ width: '100%' }}
                                filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                                onChange={this.handleOnNotificationType}
                              >
                                {
                                  masterData.notification_types !== undefined
                                    ? masterData.notification_types.map((value, index) => {
                                        return <Option key={index} value={value}>{value}</Option>
                                      })
                                    : <Option key={1} value='loading ...' disabled>Loading ...</Option>
                                }
                              </Select>
                            )}
                          </FormItem>
                        </Col>
                        {
                          includes(subjectField, notificationType) &&
                            <Col xl={12} xs={24}>
                              <div>
                                <FormItem
                                  label='Subject'
                                >
                                  {getFieldDecorator('subject', {
                                    rules: [
                                      { required: true, message: 'Subject can not be empty' }
                                    ]
                                  })(
                                    <Input size='default' className='input-box' />
                                  )}
                                </FormItem>
                              </div>
                            </Col>
                        }
                        {
                          includes(showThirdPartyFields, notificationType) &&
                            <>
                              <Col xl={12} xs={24}>
                                <div>
                                  <FormItem
                                    label='Third Party Template Id'
                                    extra='eg: 1234 or HXxxxxxxxxxxxxxxxxxxxxxxxxxxxx'
                                  >
                                    {getFieldDecorator('third_party_template_id', {
                                      rules: [
                                        { required: false }
                                      ]
                                    })(
                                      <Input size='default' className='input-box' />
                                    )}
                                  </FormItem>
                                </div>
                              </Col>
                              <Col xl={12} xs={24}>
                                <div>
                                  <FormItem
                                    label='Third Party Template Type'
                                  >
                                    {getFieldDecorator('third_party_template_type', {
                                      rules: [
                                        { required: false }
                                      ]
                                    })(
                                      <Select
                                        showSearch
                                        placeholder='Select ...'
                                        style={{ width: '100%' }}
                                        filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                                      >
                                        {
                                        masterData.notification_types !== undefined
                                          ? masterData.notification_types.map((value, index) => {
                                              return <Option key={index} value={value}>{value}</Option>
                                            })
                                          : <Option key={1} value='loading ...' disabled>Loading ...</Option>
                                      }
                                      </Select>
                                    )}
                                  </FormItem>
                                </div>
                              </Col>
                              <Col xl={12} xs={24}>
                                <div>
                                  <FormItem
                                    label='Third Party Template Status'
                                  >
                                    {getFieldDecorator('third_party_template_status', {
                                      rules: [
                                        { required: false }
                                      ]
                                    })(
                                      <Select
                                        showSearch
                                        placeholder='Select ...'
                                        style={{ width: '100%' }}
                                      >
                                        <Option key={0} value={0}>False</Option>
                                        <Option key={1} value={1}>True</Option>

                                      </Select>
                                    )}
                                  </FormItem>
                                </div>
                              </Col>
                            </>
                        }
                        {
                          includes(['whatsapp', 'mobile_app_push', 'zalo', 'whatsapp_twilio'], notificationType) &&
                            <Col xl={12} xs={24}>
                              <div style={{ marginBottom: '20px' }}>
                                {paramsObject.length > 0 &&
                                  <div className='params-field'>
                                    {paramsObject.map((d, index) => {
                                      return (
                                        <div key={`params_object_${index}`}>
                                          <span>Param -{index} </span>
                                          <Row type='flex' align='middle'>
                                            <Col sm={22}><Input value={d.value} size='default' className='input-box' onChange={(e) => this.onChangeInput(e, d.id)} /></Col>
                                            <Col>
                                              <Button icon='delete' style={{ margin: '3px' }} onClick={() => this.handleOptions(d.id)} />
                                            </Col>
                                          </Row>
                                        </div>
                                      )
                                    })}
                                    <Button icon='plus' style={{ margin: '3px' }} onClick={() => this.addOptions()} />
                                  </div>}
                              </div>
                            </Col>
                        }
                      </Row>
                    </Col>
                    <RadioGroup onChange={this.handleOnEditorChange} value={this.state.plainTextSelected} style={{ marginLeft: '15px' }}>
                      <Radio style={radioStyle} value>PLAIN HTML</Radio>
                      {form.getFieldsValue()?.notification_type === 'email' && (<Radio style={radioStyle} value={false}>TEMPLATE BUILDER</Radio>)}
                    </RadioGroup>
                    <Col xs={24} sm={24}>
                      {this.state.plainTextSelected && (
                        <div style={{ display: 'flex', alignItems: 'start', gap: '20px', width: '100%' }}>
                          <div style={{ width: '50%' }}>
                            <HtmlEditorStyled isEmpty={this.state.isHtmlEmpty} isSubmit={this.state.submit}>
                              <label className='custom-label' style={{ marginBottom: '10px' }}>Body {this.state.notificationType === 'sms' ? 'SMS' : 'HTML'}</label>
                              <FormItem>
                                {getFieldDecorator('body', {
                                  rules: [
                                    { required: false }
                                  ]
                                })(<TextArea autosize={{ minRows: 10, maxRows: 20 }} style={{ marginTop: '20px' }} />)}
                              </FormItem>
                            </HtmlEditorStyled>
                          </div>
                          <div style={{ width: '50%' }}>
                            <label className='custom-label'>Preview HTML</label>
                            <div style={{ marginTop: '20px' }} dangerouslySetInnerHTML={{ __html: form.getFieldsValue()?.body }} />
                          </div>
                        </div>
                      )}

                      {!this.state.plainTextSelected && (
                        <HTMLPreviewer
                          htmlContentFunction={this.gettingDynamicHTML}
                          selectedProduct={selectedProduct}
                        />
                      )}
                    </Col>
                    {
                     this.state.plainTextSelected && this.state.notificationType !== 'sms' && (
                       <Col span={24} xs={24}>
                         <label className='custom-label'>Body (Text)</label>
                         <FormItem>
                           {getFieldDecorator('body_text', {
                             rules: [
                               { required: false }
                             ]
                           })(
                             <TextArea
                               autosize={{ minRows: 10, maxRows: 20 }}
                             />
                           )}
                         </FormItem>
                       </Col>
                     )
                    }
                  </Row>
                </Form>
              </Spin>
              <Col span={24} xs={24}>
                <div style={{ textAlign: 'right', marginTop: '20px' }}>
                  <Button
                    key='submit'
                    type='primary'
                    form='addTemplate'
                    htmlType='submit'
                    loading={submitting}
                    style={{ marginLeft: '10px' }}
                  >
                    Submit
                  </Button>
                </div>
              </Col>
            </Row>
          </EditTemplateStyled>
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

const WrappedForm = Form.create({})(AddTemplate)

export default connect(
  state => ({
    Notifications: state.Notifications,
    partners: state.Insurance.partners,
    getPartnerProductTemplate: state.Partner.getPartnerProductTemplateData
  }),
  {
    getMasterData,
    updateTemplate,
    resetNotificationsRedux,
    closeViewBodyHtml,
    addTemplate,
    resetNotificationCore,
    getPartners,
    getPartnerProductTemplateDataRequest
  })(WrappedForm)
